import{f as a,o as i,c as l,aj as t}from"./chunks/framework.CJTJR_Xv.js";const p=JSON.parse('{"title":"网站内容与升级路线","description":"整理博客当前未完成的文章内容、网站开发升级顺序与布局美化方向。","frontmatter":{"title":"网站内容与升级路线","date":"2026-06-02T00:00:00.000Z","tags":["建站日志","内容规划","Roadmap"],"description":"整理博客当前未完成的文章内容、网站开发升级顺序与布局美化方向。"},"headers":[],"relativePath":"building/网站内容与升级路线.md","filePath":"building/网站内容与升级路线.md","lastUpdated":1788599939000}'),o={name:"building/网站内容与升级路线.md"};function s(c,e,d,r,n,h){return i(),l("div",null,e[0]||(e[0]=[t('<h1 id="网站内容与升级路线" tabindex="-1">网站内容与升级路线 <a class="header-anchor" href="#网站内容与升级路线" aria-label="Permalink to &quot;网站内容与升级路线&quot;">​</a></h1><p>这篇记录用于统一管理博客接下来的内容补全、功能升级和视觉优化。原则是先保证内容结构清晰，再补齐体验能力，最后做持续性的工程优化。</p><h2 id="一、还没完成的文章内容" tabindex="-1">一、还没完成的文章内容 <a class="header-anchor" href="#一、还没完成的文章内容" aria-label="Permalink to &quot;一、还没完成的文章内容&quot;">​</a></h2><h3 id="_1-优先补齐的系列" tabindex="-1">1. 优先补齐的系列 <a class="header-anchor" href="#_1-优先补齐的系列" aria-label="Permalink to &quot;1. 优先补齐的系列&quot;">​</a></h3><p><strong>Go 系列</strong> 当前已经有入门、基本语法、数据结构、面向对象和 Gin 文章，但索引里的路线还有大量未完成项。</p><p><strong>前端系列</strong> 目录中还有很多计划项没有对应文章。</p><p><strong>操作系统系列</strong> 已有进程、存储、文件、I/O 等主题，但部分文章缺少 frontmatter。</p><p><strong>Android 系列</strong> 目前只有索引与基本的 Android 组件介绍。</p><p><strong>UE5 系列</strong> 目前只有索引。</p><h3 id="_2-需要整理的旧文章" tabindex="-1">2. 需要整理的旧文章 <a class="header-anchor" href="#_2-需要整理的旧文章" aria-label="Permalink to &quot;2. 需要整理的旧文章&quot;">​</a></h3><p>这些文章更适合做“质量整理”，不是新增大内容：</p><ul><li><code>我的第一篇博客</code>：作为历史记录保留即可，可以加一个开头说明“早期建站记录”。</li><li><code>GitHub食用指南</code>：标题和术语可以统一空格，例如 <code>GitHub 食用指南</code>。</li><li><code>Nova HTTP框架的设计、开发与测试</code>：内容比较完整，可以作为近期重点文章，继续补充 benchmark 结论和项目链接。</li><li><code>Electron 踩坑记</code>：适合归入“开发日志”标签，和建站日志区分开。</li></ul><h2 id="二、网站开发升级顺序" tabindex="-1">二、网站开发升级顺序 <a class="header-anchor" href="#二、网站开发升级顺序" aria-label="Permalink to &quot;二、网站开发升级顺序&quot;">​</a></h2><h3 id="第一阶段-内容结构稳定" tabindex="-1">第一阶段：内容结构稳定 <a class="header-anchor" href="#第一阶段-内容结构稳定" aria-label="Permalink to &quot;第一阶段：内容结构稳定&quot;">​</a></h3><p>目标是让读者能快速判断“这里有什么、该从哪里看”。</p><ol><li>统一文章 frontmatter</li><li>修正 README 中脚本说明，例如 <code>preview</code> 和 <code>serve</code> 不一致的问题</li><li>为 <code>building</code> 增加侧边栏，<code>posts</code> 暂时保留时间线</li><li>暂不单独拆 <code>life</code> 板块，先使用 <code>tags</code> 区分生活内容</li></ol><h3 id="第二阶段-阅读体验增强" tabindex="-1">第二阶段：阅读体验增强 <a class="header-anchor" href="#第二阶段-阅读体验增强" aria-label="Permalink to &quot;第二阶段：阅读体验增强&quot;">​</a></h3><p>目标是让已有内容更好读。</p><ol><li>优化 Timeline 的时间线样式</li><li>首页减少装饰感，突出最新文章和系列入口</li><li>统一文章卡片、系列卡片、状态卡片的圆角、边框和阴影</li><li>移动端检查标题、标签、按钮是否换行稳定</li></ol><h3 id="第三阶段-互动能力" tabindex="-1">第三阶段：互动能力 <a class="header-anchor" href="#第三阶段-互动能力" aria-label="Permalink to &quot;第三阶段：互动能力&quot;">​</a></h3><p>目标是让文章能承接反馈。</p><ol><li>基于 GitHub Discussions 接入 giscus</li><li>只在文章页开启评论，首页、索引页、组件文档页不开启</li><li>评论组件配置放在主题配置里，不写死在组件内部</li><li>给 <code>publish: false</code> 或特殊页面提供关闭评论的 frontmatter</li></ol><h3 id="第四阶段-工程质量" tabindex="-1">第四阶段：工程质量 <a class="header-anchor" href="#第四阶段-工程质量" aria-label="Permalink to &quot;第四阶段：工程质量&quot;">​</a></h3><p>目标是降低后续维护成本。</p><ol><li>补充 <code>pnpm run type-check</code></li><li>补充 <code>pnpm run build</code></li><li>清理已生成的 <code>.vitepress/.temp</code>、<code>.vitepress/dist</code> 对仓库状态的影响</li><li>梳理 CI/CD 文档和实际 workflow 是否一致</li></ol><h2 id="三、布局美化方向" tabindex="-1">三、布局美化方向 <a class="header-anchor" href="#三、布局美化方向" aria-label="Permalink to &quot;三、布局美化方向&quot;">​</a></h2><h3 id="首页" tabindex="-1">首页 <a class="header-anchor" href="#首页" aria-label="Permalink to &quot;首页&quot;">​</a></h3><ul><li>Hero 区保持首屏信号清晰：头像、站点标语、主要入口。</li><li>最新文章和系列专栏作为首页主体，减少纯装饰元素。</li><li>统计卡片保持轻量，避免和文章卡片抢视觉优先级。</li></ul><h3 id="文章列表" tabindex="-1">文章列表 <a class="header-anchor" href="#文章列表" aria-label="Permalink to &quot;文章列表&quot;">​</a></h3><ul><li><code>posts</code> 继续使用时间线，适合按时间浏览。</li><li><code>series</code> 使用卡片入口和侧边栏，适合体系化学习。</li><li><code>building</code> 使用时间线加侧边栏，适合记录迭代过程。</li></ul><h3 id="评论区" tabindex="-1">评论区 <a class="header-anchor" href="#评论区" aria-label="Permalink to &quot;评论区&quot;">​</a></h3><ul><li>评论区应放在正文之后、上一篇/下一篇导航之前或之后都可以。</li><li>视觉上保持轻量，不要让评论组件成为文章主体。</li></ul><h2 id="四、近期执行清单" tabindex="-1">四、近期执行清单 <a class="header-anchor" href="#四、近期执行清单" aria-label="Permalink to &quot;四、近期执行清单&quot;">​</a></h2><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 建立内容与升级路线文档</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 统一缺失 frontmatter 的系列文章</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 优化 Timeline 样式</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 为 <code>building</code> 配置侧边栏</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 接入 giscus 评论</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 检查 README 与 package scripts 是否一致</li></ul>',34)]))}const b=a(o,[["render",s]]);export{p as __pageData,b as default};
